//   GEMM N = output channels (32)
//   GEMM K = CIN*K*K = 27 (padded to 32)
// Each block has 16 warps; each warp computes a 32(pixels) x 32(channels)
// tile as a 2x2 grid of 16x16x16 bf16 MMA fragments.
__global__ void __launch_bounds__(THREADS, 2) conv2d_3x3_cin3_cout32_bf16_kernel(
    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
