  // loaded, so they share storage with the bf16 epilogue buffer; staging
  // the epilogue in bf16 (instead of float) halves its footprint. In
  // addition, the raw input tile (sX) is dead once the im2col operand sA
  // has been built, so the weight buffer (sW) overlays sX. This dead-buffer
  // reuse keeps the union at ~36 KB per block (still 2 blocks/SM). The
  // wider 16x32 spatial tile halves the block count, cuts redundant halo
  // input loads, and widens global store chunks (improved spatial tiling).
  __shared__ __align__(32) union {
    struct {
      __nv_bfloat16 sA[TILE_M][KTILE];
      union {
        __nv_bfloat16 sX[CIN][TILE_IH][TILE_IW_PAD];
        __nv_bfloat16 sW[COUT][KTILE];
      } sxw;
    } stage;
    __nv_bfloat16 sOut16[TILE_M][OUT_LDS];
