    const int m = idx >> 5;
    const int k = idx & 31;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (k < CIN * K * K) {
      const int ci = k / 9;
      const int r = k - ci * 9;
      const int kh = r / 3;
      const int kw = r - kh * 3;
      v = smem.stage.sxw.sX[ci][(m >> 5) + kh][(m & 31) + kw];
    }
    smem.stage.sA[m][k] = v;
