    wmma::load_matrix_sync(a[1], &smem.stage.sA[m0 + 16][ki * 16], KTILE);
    wmma::load_matrix_sync(b[0], &smem.stage.sxw.sW[0][ki * 16], KTILE);
    wmma::load_matrix_sync(b[1], &smem.stage.sxw.sW[16][ki * 16], KTILE);
    wmma::mma_sync(acc[0][0], a[0], b[0], acc[0][0]);
    wmma::mma_sync(acc[0][1], a[0], b[1], acc[0][1]);
    wmma::mma_sync(acc[1][0], a[1], b[0], acc[1][0]);
    wmma::mma_sync(acc[1][1], a[1], b[1], acc[1][1]);
  }
  // All reads of the staging region must finish before the bf16 epilogue
  // buffer overwrites it (sOut16 aliases the staging shared memory).
  __syncthreads();
  // Convert the float accumulator fragments to bf16 in registers and stage
  // them in shared memory (16x16 accumulator layout: lane/4 = row group,
  // (lane%4)*2 = column pair, upper/lower 8-row and 8-column halves).
  const int lane = tid & 31;
  const int frow = lane >> 2;
  const int fcol = (lane & 3) * 2;
#pragma unroll
  for (int i = 0; i < 2; ++i) {
#pragma unroll
    for (int j = 0; j < 2; ++j) {
      const int rb = warp * 32 + i * 16 + frow;
      const int cb = j * 16 + fcol;
#pragma unroll
      for (int e = 0; e < 8; ++e) {
        smem.sOut16[rb + ((e & 2) ? 8 : 0)][cb + (e & 1) + ((e & 4) ? 8 : 0)] =
            __float2bfloat16_rn(acc[i][j].x[e]);
      }
    }
  }
  __syncthreads();
  // Write results back: each iteration covers 8 consecutive output pixels
  // within one tile row (one 16-byte store chunk when the destination is
  // 16B-aligned and fully in-bounds, 4B pair stores otherwise). All stores
  // use the streaming cache hint (evict-first): the output is written once
  // and never re-read, so keeping it out of L2 preserves L2 capacity for
  // input/weight reads and improves effective DRAM throughput (the kernel
  // is DRAM-bound at ~80% and output stores dominate its traffic).
  for (int idx = tid; idx < (TILE_M / 8) * COUT; idx += THREADS) {
    const int co = idx >> 6;
    const int pix = (idx & 63) << 3;  // first of 8 consecutive pixels
    const int oh = oh0 + (pix >> 5);
    const int ow = ow0 + (pix & 31);
    __nv_bfloat16* dst = &y[((long long)(n * COUT + co) * Ho + oh) * Wo + ow];
    if (oh < Ho && (ow + 7) < Wo && ((reinterpret_cast<size_t>(dst) & 15) == 0)) {
      __nv_bfloat162 p0, p1, p2, p3;
      p0.x = smem.sOut16[pix][co];
      p0.y = smem.sOut16[pix + 1][co];
      p1.x = smem.sOut16[pix + 2][co];
      p1.y = smem.sOut16[pix + 3][co];
      p2.x = smem.sOut16[pix + 4][co];
      p2.y = smem.sOut16[pix + 5][co];
      p3.x = smem.sOut16[pix + 6][co];
      p3.y = smem.sOut16[pix + 7][co];
      uint4 v;
      v.x = *reinterpret_cast<unsigned int*>(&p0);
      v.y = *reinterpret_cast<unsigned int*>(&p1);
      v.z = *reinterpret_cast<unsigned int*>(&p2);
      v.w = *reinterpret_cast<unsigned int*>(&p3);
      __stcs(reinterpret_cast<uint4*>(dst), v);
    } else {
#pragma unroll
      for (int k = 0; k < 8; k += 2) {
        const int owk = ow + k;
        __nv_bfloat16* d2 = &y[((long long)(n * COUT + co) * Ho + oh) * Wo + owk];
        if (oh < Ho && (owk + 1) < Wo && ((reinterpret_cast<size_t>(d2) & 3) == 0)) {
          __nv_bfloat162 v2;
          v2.x = smem.sOut16[pix + k][co];
          v2.y = smem.sOut16[pix + k + 1][co];
          __stcs(reinterpret_cast<unsigned int*>(d2), *reinterpret_cast<unsigned int*>(&v2));
        } else {
          if (oh < Ho && owk < Wo) {
            __nv_bfloat16 v0 = smem.sOut16[pix + k][co];
            __stcs(reinterpret_cast<unsigned short*>(d2), *reinterpret_cast<unsigned short*>(&v0));
          }
          if (oh < Ho && (owk + 1) < Wo) {
            __nv_bfloat16 v1 = smem.sOut16[pix + k + 1][co];
            __stcs(reinterpret_cast<unsigned short*>(d2 + 1), *reinterpret_cast<unsigned short*>(&v1));
          }
        }
      }
    }
  }
}
